{"id":"79c2398d-eca5-4c1c-bd93-e2f95f5889f0","type":"https://serlo.org/editor","variant":"serlo-org","domainOrigin":"serlo.org","version":2,"editorVersion":"0.22.0","dateModified":"2025-02-26T18:27:05.856Z","document":{"plugin":"exerciseGroup","state":{"content":{"plugin":"rows","state":[{"plugin":"multimedia","state":{"explanation":{"plugin":"rows","state":[{"plugin":"text","state":[{"type":"p","children":[{"text":"Alle Angaben in mm; die Abbildung ist nicht maßstabsgerecht."}]}],"id":"64761f2b-ab56-4a35-b005-8e267246fafe"}],"id":"a7d221ec-7e93-4662-a188-df219f238c29"},"multimedia":{"plugin":"image","state":{"src":"https://assets.serlo.org/a3599910-f5c3-11ee-814e-afbc5abe3304/image.jpg","caption":{"plugin":"text","state":[{"type":"p","children":[{"text":""}]}],"id":"05d86bfb-de31-4361-ba02-149f73ee9905"}},"id":"ae39db66-e8d8-4dc8-860b-457f923b3d54"},"illustrating":true,"width":50},"id":"9c370c0d-6d72-4265-bfe2-afda040f3fd7"}],"id":"04c16ae2-1f58-4fe7-a5a5-12149fb7e853"},"exercises":[{"plugin":"exercise","state":{"content":{"plugin":"rows","state":[{"plugin":"text","state":[{"type":"p","children":[{"text":"Berechne das Volumen des abgebildeten Hammerkopfs, ohne die Öffnung für den Stiel zu beachten. "},{"text":"(3 Punkte)","strong":true}]}],"id":"6b458a9c-1a0c-4b3a-947c-0a284fe7499b"}],"id":"8d9f5b43-9b12-4342-95d7-76cc8ac32987"},"interactive":{"plugin":"inputExercise","state":{"type":"input-expression-equal-match-challenge","unit":"mm³","answers":[{"value":"43100","isCorrect":true,"feedback":{"plugin":"text","state":[{"type":"p","children":[{"text":"Sehr gut!"}]}],"id":"f6b36a13-7d4c-4618-a138-50fdd9642b4e"}},{"value":"43113,5 ","isCorrect":true,"feedback":{"plugin":"text","state":[{"type":"p","children":[{"text":"Sehr gut!"}]}],"id":"36a9df13-3052-48af-bd3d-76fb01653dc7"}}]},"id":"5f5a7d76-dd9c-40ea-95e2-96160c6a2725"},"solution":{"plugin":"solution","state":{"strategy":{"plugin":"text","state":[{"children":[{"children":[{"type":"list-item-child","children":[{"text":"Verwende die Formel zur Berechnung des Volumens eines Prismas."}]}],"type":"list-item"}],"type":"unordered-list"}],"id":"80c6a338-e071-427f-920e-63c4484f461e"},"steps":{"plugin":"rows","state":[{"plugin":"text","state":[{"type":"p","children":[{"text":"Der Hammerkopf ist ein Prisma mit einer Grundfläche, welche sich aus einem Rechteck und einem Dreieck zusammensetzt."}]},{"type":"h","children":[{"text":"Flächeninhalt der Grundfläche"}],"level":2},{"type":"p","children":[{"text":"Wir berechnen zunächst den Flächeninhalt der Grundfläche "},{"type":"math","src":"G","inline":true,"children":[{"text":""}]},{"text":", indem wir die Fläche des Rechtecks "},{"type":"math","src":"\mathrm{A_{Rechteck}}","inline":true,"children":[{"text":""}]},{"text":" und des Dreiecks "},{"type":"math","src":"\mathrm{A_{Dreieck}}","inline":true,"children":[{"text":""}]},{"text":" addieren."}]},{"type":"p","children":[{"text":"Es gilt:"}]},{"type":"p","children":[{"text":""}]},{"type":"math","src":"\begin{aligned}
\text{A}_{\text{Rechteck}} &= 23 \cdot 58 = 1334\\
\text{A}_{\text{Dreieck}} &= \frac{1}{2}\cdot 23\cdot (105-58) = 540,5\\
\end{aligned}","inline":false,"children":[{"text":""}]},{"type":"p","children":[{"text":"Damit erhalten wir für die Grundfläche:"}]},{"type":"math","src":"\mathrm{G = A_{\text{Rechteck}} + A_{\text{Dreieck}} = 1334 + 540,5 = 1874,5}","inline":false,"children":[{"text":""}]},{"type":"h","children":[{"text":"Volumen des Hammerkopfes"}],"level":2},{"type":"p","children":[{"text":"Somit ergibt sich insgesamt für das Volumen "},{"type":"math","src":"\text{V}","inline":true,"children":[{"text":""}]},{"text":", da die Höhe "},{"type":"math","src":"\text{h}","inline":true,"children":[{"text":""}]},{"text":" des Prismas hier "},{"type":"math","src":"23","inline":true,"children":[{"text":""}]},{"text":" ist:"}]},{"type":"math","src":"\mathrm{V = G\cdot h = 1874,5\cdot 23 = 43113,5}","inline":false,"children":[{"text":""}]},{"type":"p","children":[{"text":"Das Volumen des Hammerkopfes beträgt also ungefähr "},{"type":"math","src":"43~100\mathrm{~mm}^3","inline":true,"children":[{"text":""}]},{"text":" bzw. umgerechnet "},{"type":"math","src":"43,1\mathrm{~cm}^3","inline":true,"children":[{"text":""}]},{"text":"."}]}],"id":"057aa17a-f64c-43c9-a860-79269b43375e"},{"plugin":"spoiler","state":{"richTitle":{"plugin":"text","state":[{"type":"p","children":[{"text":"Alternative Lösung"}]}],"id":"2e4bbe65-4fc2-473e-9669-52fa9501608e"},"content":{"plugin":"rows","state":[{"plugin":"text","state":[{"type":"p","children":[{"text":"Eventuell fällt es Dir leichter, den Hammerkopf als Quader mit aufgesetztem Dreiecksprisma anstatt als allgemeines Prisma zu betrachten."}]},{"type":"p","children":[{"text":"In diesem Fall kannst Du auch die einzelnen Volumina berechnen und diese dann addieren."}]},{"type":"p","children":[{"text":"So ergibt sich zuerst:"}]},{"type":"p","children":[{"text":""}]},{"type":"math","src":"\begin{aligned}
\text{V}_{\text{Dreiecksprisma}} &= \frac{1}{2}\cdot 23 \cdot (105-58) \cdot 23 = 12431,5\\
\text{V}_{\text{Quader}} &= 23\cdot 58 \cdot 23 = 30682
\end{aligned}","inline":false,"children":[{"text":""}]},{"type":"p","children":[{"text":"Und dadurch wieder für das Gesamtvolumen:"}]},{"type":"math","src":"\mathrm{V = V_{\text{Dreiecksprisma}} + V_{\text{Quader}} = 12431,5+30682 = 43113,5}","inline":false,"children":[{"text":""}]},{"type":"p","children":[{"text":""}]}],"id":"d18b0d8b-005f-47d4-88da-93f3d6fe86fc"}],"id":"7b75a3fc-3359-450a-9deb-ba8a66dcaae2"}},"id":"bc8cae75-a13a-48f8-a5f0-6f3d37aef652"}],"id":"238aefd1-ae2c-4d1c-b044-ad8ade44fb4a"},"prerequisite":{"id":"1625","title":"Prisma"}},"id":"0edeef8e-69e9-4fec-aec7-effeeac3ab16"},"hideInteractiveInitially":true},"id":"9d1d1000-5443-4dd4-a2b5-b34eb2cf8006"},{"plugin":"exercise","state":{"content":{"plugin":"rows","state":[{"plugin":"text","state":[{"type":"p","children":[{"text":"Thilo möchte überprüfen, ob der Hammerkopf wirklich aus Stahl besteht. Er berechnet die Dichte "},{"type":"math","src":"\rho","inline":true,"children":[{"text":""}]},{"text":" mit der Formel:"}]},{"type":"p","children":[{"text":""},{"type":"math","src":"\mathrm{m=V \cdot \rho}","inline":true,"children":[{"text":""}]},{"text":""}]},{"type":"p","children":[{"text":"Beim Volumen "},{"type":"math","src":"\text{V}","inline":true,"children":[{"text":""}]},{"text":" beachtet er die Öffnung für den Stiel nicht und erhält deshalb ein falsches Ergebnis."}]},{"type":"p","children":[{"text":"Entscheide","strong":true},{"text":", ob Thilos Ergebnis für die Dichte zu groß oder zu klein ist und "},{"text":"begründe","strong":true},{"text":" deine Meinung. "},{"text":"(2 Punkte)","strong":true}]}],"id":"b6565bfe-7f39-4a8f-b162-d60a9251abc8"}],"id":"8130391b-be68-4eec-95bb-68a1a5ff0a37"},"interactive":{"plugin":"scMcExercise","state":{"isSingleChoice":true,"answers":[{"content":{"plugin":"text","state":[{"type":"p","children":[{"text":"Thilos Ergebnis ist zu groß."}]}],"id":"f7d53e34-c2ed-466b-a6b9-9f6d82e06e48"},"isCorrect":false,"feedback":{"plugin":"text","state":[{"type":"p","children":[{"text":"Leider falsch, überprüfe deine Begründung."}]}],"id":"dbc511f3-3950-4261-8588-2832a4312ac8"}},{"content":{"plugin":"text","state":[{"type":"p","children":[{"text":"Thilos Ergebnis ist zu klein."}]}],"id":"4145a951-269d-40b3-9900-e601e86f0dee"},"isCorrect":true,"feedback":{"plugin":"text","state":[{"type":"p","children":[{"text":"Sehr gut! Kannst du das auch begründen?"}]}],"id":"6b69b7c9-1a53-4a1c-bdf3-59a473897cde"}},{"content":{"plugin":"text","state":[{"type":"p","children":[{"text":"Man kann nicht entscheiden, ob Thilos Ergebnis zu groß oder klein ist."}]}],"id":"d124c41a-a3f6-461b-9048-71dcf2d17689"},"isCorrect":false,"feedback":{"plugin":"text","state":[{"type":"p","children":[{"text":"Leider falsch, überprüfe deine Begründung."}]}],"id":"6130949b-e130-4bf7-949e-b89d6a03ae3c"}}]},"id":"7dda8b39-deea-4940-8c12-dafc10016d66"},"solution":{"plugin":"solution","state":{"strategy":{"plugin":"text","state":[{"type":"p","children":[{"text":""}]}],"id":"aa409707-cee1-47b7-90bf-ddba33bd7d7b"},"steps":{"plugin":"rows","state":[{"plugin":"text","state":[{"type":"p","children":[{"text":"Indem wir die gegebene Formel nach der Dichte umstellen, erhalten wir "},{"type":"math","src":"\mathrm{\rho = \frac{m}{V}}","inline":true,"children":[{"text":""}]},{"text":"."}]},{"type":"p","children":[{"text":"Da Thilo beim Volumen nicht die Öffnung für den Stiel beachtet hat, die normalerweise beim Volumen nicht dazugezählt werden würde, ist seine Volumensangabe zu "},{"text":"groß","strong":true},{"text":"."}]},{"type":"p","children":[{"text":"Also teilen wir bei der Berechnung der Dichte "},{"type":"math","src":"\rho","inline":true,"children":[{"text":""}]},{"text":" durch eine zu große Zahl und erhalten damit ein "},{"type":"math","src":"","inline":true,"children":[{"text":""}]},{"text":"zu kleines","strong":true},{"text":" Ergebnis."}]}],"id":"032303a2-e708-4cbc-93ee-2d39257afc1a"}],"id":"4623f00a-01a1-42f8-97b2-5fadbfb423b5"}},"id":"7bcc8ef1-715d-4b20-87aa-a4af3f1a4878"},"hideInteractiveInitially":true},"id":"2ea87a2f-613e-4b78-a499-2c5daab8489d"},{"plugin":"exercise","state":{"content":{"plugin":"rows","state":[{"plugin":"text","state":[{"type":"p","children":[{"text":"Die Öffnung für den Stiel ist nicht kreisrund."}]}],"id":"0d6804f9-4231-48dd-9d9f-545d5bc5a798"},{"plugin":"multimedia","state":{"explanation":{"plugin":"rows","state":[{"plugin":"text","state":[{"type":"p","children":[{"text":"Die Abbildung ist nicht maßstabsgerecht."}]}],"id":"a8dbec69-7a6b-49b2-b2a5-d064e0275162"}],"id":"6aeb8b30-4d16-4d69-8502-bed25fe24d36"},"multimedia":{"plugin":"image","state":{"src":"https://assets.serlo.org/d621a0e0-f5c3-11ee-814e-afbc5abe3304/image.jpg","caption":{"plugin":"text","state":[{"type":"p","children":[{"text":""}]}],"id":"dfcfa91d-d754-46a1-86e6-53863af9a86d"}},"id":"db24ea35-d41f-4481-ae6b-2591967f61ca"},"illustrating":true,"width":50},"id":"18e04a2b-8145-42b1-bbeb-3ef96fa1f08d"},{"plugin":"text","state":[{"type":"p","children":[{"text":"Zeige","strong":true},{"text":", dass der Flächeninhalt der abgebildeten Öffnung zwischen "},{"type":"math","src":"1,5 \mathrm{~cm}^{2}","inline":true,"children":[{"text":""}]},{"text":" und "},{"type":"math","src":"3,5 \mathrm{~cm}^{2}","inline":true,"children":[{"text":""}]},{"text":" liegen muss. "},{"text":"(2 Punkte)","strong":true}]}],"id":"de4629b7-c9e7-4595-9e6e-740af02dcace"}],"id":"8f7789fd-d4ec-4d32-8dab-c1cec03d06d0"},"solution":{"plugin":"solution","state":{"strategy":{"plugin":"text","state":[{"children":[{"children":[{"type":"list-item-child","children":[{"text":"Versuche, die Fläche durch einfachere Flächen (zum Beispiel Rechtecke, Kreise oder Rauten) abzuschätzen."}]}],"type":"list-item"}],"type":"unordered-list"}],"id":"4620234c-28d8-4742-8a07-702838974801"},"steps":{"plugin":"rows","state":[{"plugin":"text","state":[{"type":"h","children":[{"text":"Wenn das Loch größer wäre..."}],"level":2}],"id":"e9c2b673-864a-4ecb-9369-79b7198ed281"},{"plugin":"multimedia","state":{"explanation":{"plugin":"rows","state":[{"plugin":"text","state":[{"type":"p","children":[{"text":"Wir überlegen uns zunächst, dass der Flächeninhalt nicht größer als "},{"type":"math","src":"3,5\mathrm{~cm}^2","inline":true,"children":[{"text":""}]},{"text":" sein kann, denn die Öffnung ist in einem Rechteck mit Seitenlängen "},{"type":"math","src":"1,4\mathrm{~cm}","inline":true,"children":[{"text":""}]},{"text":" und "},{"type":"math","src":"2,5\mathrm{~cm}","inline":true,"children":[{"text":""}]},{"text":" enthalten."}]},{"type":"p","children":[{"text":"Der Flächeninhalt des Rechtecks beträgt also "},{"type":"math","src":"3,5\mathrm{~cm}^2","inline":true,"children":[{"text":""}]},{"text":" (denn "},{"type":"math","src":"1,4\cdot 2,5 = 3,5","inline":true,"children":[{"text":""}]},{"text":") und damit ist auch der Flächeninhalt der Öffnung kleiner als "},{"type":"math","src":"3,5\mathrm{~cm}^2","inline":true,"children":[{"text":""}]},{"text":"."}]}],"id":"ae0b1fe1-632f-401a-ab59-d6d0bc36c7c6"}],"id":"324cc5b2-f138-461e-af38-9515ca39b3d1"},"multimedia":{"plugin":"image","state":{"src":"https://assets.serlo.org/79734a40-081c-11ef-90cb-b1de64cc54d3/image.png","caption":{"plugin":"text","state":[{"type":"p","children":[{"text":"Abschätzung mithilfe eines Rechtecks"}]}],"id":"01055339-7464-4563-8f07-478ca40b7004"}},"id":"9ec4ad2c-5034-4474-a992-58153707d002"},"illustrating":true,"width":50},"id":"d4b229ec-91f8-477d-9da2-59d404548f0f"},{"plugin":"text","state":[{"type":"h","children":[{"text":"Wenn das Loch größer kleiner wäre..."}],"level":2}],"id":"44972158-3df3-433b-bf1a-a06513127a1b"},{"plugin":"multimedia","state":{"explanation":{"plugin":"rows","state":[{"plugin":"text","state":[{"type":"p","children":[{"text":"Für die untere Schranke können wir zum Beispiel feststellen, dass ein Kreis mit Durchmesser "},{"type":"math","src":"1,4\mathrm{~cm}","inline":true,"children":[{"text":""}]},{"text":" in der Öffnung enthalten ist."}]},{"type":"p","children":[{"text":"Da der Radius dieses Kreises also "},{"type":"math","src":"0,7\mathrm{~cm}","inline":true,"children":[{"text":""}]},{"text":" lang ist, beträgt sein Flächeninhalt "},{"type":"math","src":"1,54\mathrm{~cm}^2","inline":true,"children":[{"text":""}]},{"text":", wie wir mithilfe der Rechnung "},{"type":"math","src":"\pi\cdot (0,7)^2 \approx 1,54","inline":true,"children":[{"text":""}]},{"text":" bestimmt haben."}]},{"type":"p","children":[{"text":"Damit ist auch der Flächeninhalt der Öffnung größer als "},{"type":"math","src":"1,5\mathrm{~cm}^2","inline":true,"children":[{"text":""}]},{"text":"."}]}],"id":"b964e96c-723d-46ca-99cf-58335ef2f984"}],"id":"be3f3f38-3b42-4b15-8a29-15051473484f"},"multimedia":{"plugin":"image","state":{"src":"https://assets.serlo.org/01b94e90-081d-11ef-90cb-b1de64cc54d3/image.png","caption":{"plugin":"text","state":[{"type":"p","children":[{"text":"Abschätzung mithilfe eines Kreises"}]}],"id":"2bd7cb1f-ba37-4865-a267-ddc5c20cdae1"}},"id":"af956e93-6a60-4208-a2a6-aad9ad02d1a2"},"illustrating":true,"width":50},"id":"4ba40c52-a0df-4cab-a206-42933115e7ce"}],"id":"05d376ee-bdc5-48aa-95ad-cbf8b4deec81"}},"id":"214d1c0d-18ae-42bc-8054-db369ae4227d"}},"id":"ee645bfb-cfdb-4290-8f7a-bca497becb10"}]},"id":"909457f5-cfdb-43e6-8bd6-46832349e8ac"}}
